from pydantic import BaseModel, Field, ValidationError
from typing import List
class M(BaseModel):
    id: str
try:
    M()
except ValidationError as e:
    print(e.errors())

from pydantic import BaseModel, Field, ValidationError
class Item(BaseModel):
    quantity: int
try:
    Item(quantity="many")
except ValidationError as e:
    print(e.errors())

from pydantic import BaseModel, Field, ValidationError
class M(BaseModel):
    sku: str = Field(min_length=3)
try:
    M(sku="ab")
except ValidationError as e:
    print(e.errors())

from pydantic import BaseModel, Field, ValidationError
class M(BaseModel):
    zip_code: str = Field(pattern=r'^\d{5}$')
try:
    M(zip_code='xx')
